  vec3 worldNormal=normalize(worldNormalMatrix*h.normal);
  bool back=dot(worldNormal,worldDirection)>0.0;
  if (back) { worldNormal=-worldNormal; }
  vec4 viewHit=viewMatrix*vec4(worldHit,1.0);
