  for (int i=0;i<1;i++) { irradiance+=getHemisphereLightIrradiance(hemisphereLights[i],normal); }
  #endif
  #if 2 > 0
  for (int i=0;i<2;i++) { irradiance+=max(dot(normal,directionalLights[i].direction),0.0)*directionalLights[i].color; }
  #endif
  gl_FragColor=vec4(slotColor[h.slot]*irradiance*RECIPROCAL_PI+slotEmission[h.slot],1.0);
