	gl_FragColor.rgb = toneMapping( gl_FragColor.rgb );
#endif
gl_FragColor = linearToOutputTexel( gl_FragColor );
  #ifdef USE_FOG
  float fogFactor=smoothstep(fogNear,fogFar,-viewHit.z);
  gl_FragColor.rgb=mix(gl_FragColor.rgb,fogColor,fogFactor);
  #endif
}

